const counts = [9, 9, 9, 9, 10, 9, 9, 9, 11, 10, 12, 11, 10, 11];
const mixes: Array<[number, number, number]> = [[2,4,3],[2,4,3],[2,4,3],[2,4,3],[2,5,3],[2,4,3],[2,4,3],[2,4,3],[2,6,3],[2,5,3],[2,6,4],[2,6,3],[2,5,3],[2,6,3]];
const STRING_LITERAL = /"(?:[^"\\]|\\.)*"/g;
/** Spacing only (`e:Exception` -> `e: Exception`); the app lays out braces and semicolons itself. */
const tidyLine = (line: string): string => {
  if (/^\s*\/\//.test(line)) return line;
  const indent = line.match(/^\s*/)![0];
  const strings: string[] = [];
  const masked = line.trim().replace(STRING_LITERAL, (m) => `\u0000${strings.push(m) - 1}\u0000`);
  const spaced = masked
    .replace(/(\w)\s*:\s*(?=[A-Za-z])/g, '$1: ')
    .replace(/\s*(?<![=!<>+\-*/%])=(?![=>])\s*/g, ' = ')
    .replace(/,(?=\S)/g, ', ')
    .replace(/\)\{/g, ') {')
    .replace(/(\w)\{/g, '$1 {')
    .replace(/\}(?=catch|finally|else)/g, '} ')
    .replace(/\b(catch|if|while|for|when)\(/g, '$1 (')
    .replace(/\s{2,}/g, ' ');
  return indent + spaced.replace(/\u0000(\d+)\u0000/g, (_m, i) => strings[Number(i)]);
};
const tidyLines = (lines: string[]) => lines.map(tidyLine);
/** One statement per line: split a line at every `;` that is outside strings, braces and parentheses. */
const splitStatements = (line: string): string[] => {
  const parts: string[] = [];
  let depth = 0, start = 0, quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quoted) { if (c === '\\') i++; else if (c === '"') quoted = false; continue; }
    if (c === '"') quoted = true;
    else if (c === '{' || c === '(') depth++;
    else if (c === '}' || c === ')') depth--;
    else if (c === ';' && depth === 0) { parts.push(line.slice(start, i)); start = i + 1; }
  }
  parts.push(line.slice(start));
  return parts.map((part) => part.trim()).filter(Boolean);
};
const code = (lines: string[]) => {
  const statements = lines.flatMap(splitStatements).map(tidyLine);
  return statements.some((line) => /^\s*fun main\b/.test(line)) ? statements : ['fun main() {', ...statements.map((line) => `  ${line}`), '}'];
};

