const GENERIC_PROMPT = /which answer matches this Kotlin scenario\?$/;
const plainPrompt = (prompt: string) => {
  const text = prompt.replace(/^[A-Za-z/\- ]+ question: /, '');
  return text.charAt(0).toUpperCase() + text.slice(1);
};

const direct: QuizQuestion[] = [];
WORLD_15_LESSONS.slice(0, 14).forEach((lesson, lessonIndex) => {
  const questions: QuizQuestion[] = [];
  const spec = extras[lessonIndex];
  const suffix = lesson.id.replace('world-15-', '');
  const makeId = () => `w15q-${suffix}-${questions.length + 1}`;
  questions.push({ ...base(makeId(), lesson.id, lesson.topicTitle, `core fact: ${lesson.learn.keyIdeas[0].title}`, 'easy', spec.fact[0], spec.fact[2], 'Separate compile-time rules, runtime control flow, and recovery behavior.'), type: 'true_false', answer: spec.fact[1] });
  questions.push({ ...base(makeId(), lesson.id, lesson.topicTitle, `design choice: ${lesson.learn.keyIdeas[1].title}`, 'easy', spec.choice[0], spec.choice[3], 'Choose the narrowest behavior that preserves useful failure information.'), type: 'single_choice', options: [spec.choice[1], ...spec.choice[2]], answer: 0 });
  for (const [sourceIndex, source] of (lesson.predict?.questions ?? []).entries()) {
    const fix = FIXES[`${lessonIndex}.${sourceIndex}`];
    const labels = fix?.options ?? source.options.map((option) => option.label.replace(/\\n/g, '\n'));
    const answer = fix?.options ? 0 : source.options.findIndex((option) => option.isCorrect);
    const correct = labels[answer] ?? '';
    const outputPrompt = /output|printed|prints|output order/i.test(source.prompt);
    const behavioralAnswer = /propagat|throws?|handled by|branch runs|compile|required|must |cannot |does not |because|Kotlin callers|silently|hidden|meaningful recovery/i.test(correct);
    const output = fix?.kind ? fix.kind === 'out' : outputPrompt && !behavioralAnswer;
    const scenario = source.title || source.topicMeta;
    const explanation = fix?.exp ?? source.explanation.detail;
    if (/independently of the other scenarios/.test(explanation)) throw new Error(`World 15 ${lesson.id} predict ${sourceIndex} needs a real explanation`);
    if (!output && !fix?.q && GENERIC_PROMPT.test(source.prompt)) throw new Error(`World 15 ${lesson.id} predict ${sourceIndex} needs a real prompt`);
    const prompt = fix?.q ?? (output ? `What is the exact output of this “${scenario}” example?` : plainPrompt(source.prompt));
    questions.push({ ...base(makeId(), lesson.id, lesson.topicTitle, fix?.concept ?? scenario, 'medium', prompt, explanation, 'Trace the successful, handled, propagated, or captured path precisely.'), type: output ? 'predict_output' : 'single_choice', code: code(fix?.code ?? source.code ?? []), options: labels, monoOptions: output || fix?.mono || undefined, answer } as QuizQuestion);
  }
  const supplements: QuizQuestion[] = [
    { ...base('x', lesson.id, lesson.topicTitle, 'combined semantic claims', 'medium', spec.multi[0], spec.multi[3], 'Select exactly two statements that match Kotlin behavior.'), type: 'multi_select', options: spec.multi[1], answers: spec.multi[2] },
    { ...base('x', lesson.id, lesson.topicTitle, 'behavioral comparison', 'hard', spec.compare[0], spec.compare[4], 'Compare matching, propagation, returned state, and preserved context.'), type: 'code_comparison', a: code(spec.compare[1]), b: code(spec.compare[2]), answer: spec.compare[3] },
  ];
  while (questions.length < counts[lessonIndex]) {
    const item = supplements.shift();
    if (!item) throw new Error(`World 15 allocation lacks supplements for ${lesson.id}`);
    questions.push({ ...item, id: makeId() } as QuizQuestion);
  }
  direct.push(...assignDifficulties(questions, mixes[lessonIndex]));
});

