function balance(items: QuizQuestion[]): QuizQuestion[] {
  let choice = 0, comparison = 0;
  return items.map((q) => {
    if (q.type === 'single_choice' || q.type === 'predict_output') {
      const options = [...q.options]; const correct = options.splice(q.answer, 1)[0]; const answer = choice++ % options.length + 1; options.splice(answer, 0, correct); return { ...q, options, answer };
    }
    if (q.type === 'code_comparison' && comparison++ % 2) return { ...q, a: q.b, b: q.a, answer: q.answer === 0 ? 1 : 0 };
    return q;
  });
}

const tidyQuestion = (question: QuizQuestion): QuizQuestion => {
  const fields = { ...question } as unknown as Record<string, unknown>;
  for (const key of ['code', 'a', 'b']) if (Array.isArray(fields[key])) fields[key] = tidyLines(fields[key] as string[]);
  return fields as unknown as QuizQuestion;
};

// formatQuizCodeQuestion indents by brace depth (36 snippets here were written flat) and keeps error-line targets.
export const WORLD_15_QUIZ = balance([...direct, ...setQuestions]).map(tidyQuestion).map((q) => formatQuizCodeQuestion(q));
export const WORLD_15_BOSS_QUIZ = balance(boss).map(tidyQuestion).map((q) => formatQuizCodeQuestion(q));
